import re
import json

def recover_relations(response: str, atoms: dict[str, str]) -> str:
    relations = []
    for i in range(1, len(atoms) + 1):
        for j in range(i + 1, len(atoms) + 1):
            # Check for Cause-Effect relation
            if re.search(rf"{re.escape(atoms[str(i)])}.*caused|led to|resulted in|because.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})
            # Check for Evidence relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*shows|indicates|confirms|as shown by.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Evidence", "coupling": "entailment", "strength_band": "moderate"})
            # Check for Restatement relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*that is|in other words.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})
            # Check for Refutation relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*cannot be squared with|rules out|it cannot have, since.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})
            # Check for Contrast relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*by contrast|whereas|but.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"})
            # Check for Concession relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*although|despite|even though.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Concession", "coupling": "none", "strength_band": "weak"})
            # Check for Alternative relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*either|or.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})
