                relations.append({"source": i, "target": j, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "moderate"})
            # Check for Precedence relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*came first|before.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Precedence", "coupling": "none", "strength_band": "strong"})
            # Check for Succession relation
            elif re.search(rf"{re.escape(atoms[str(i)])}.*after|then.*{re.escape(atoms[str(j)])}", response, re.IGNORECASE):
                relations.append({"source": i, "target": j, "sense": "Succession", "coupling": "none", "strength_band": "strong"})

    # Special cases
    relations.append({"source": 3, "target": 4, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})
    relations.append({"source": 11, "target": 12, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})
    relations.append({"source": 13, "target": 14, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})
    relations.append({"source": 5, "target": 6, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})
    relations.append({"source": 5, "target": 8, "sense": "Precedence", "coupling": "none", "strength_band": "strong"})

